bool DailyChallengeCompletions::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }

    if(pJson.isMember("user_id"))
    {
        if(!validJsonOfField(1, "user_id", pJson["user_id"], err, true))
            return false;
    }

    else
    {
        err="The user_id column cannot be null";
        return false;
    }

    if(pJson.isMember("challenge_id"))
    {
        if(!validJsonOfField(2, "challenge_id", pJson["challenge_id"], err, true))
            return false;
    }

    else
    {
        err="The challenge_id column cannot be null";
        return false;
    }

    if(pJson.isMember("session_id"))
    {
        if(!validJsonOfField(3, "session_id", pJson["session_id"], err, true))
            return false;
    }

    else
    {
        err="The session_id column cannot be null";
        return false;
    }

    if(pJson.isMember("completed_at"))
    {
        if(!validJsonOfField(4, "completed_at", pJson["completed_at"], err, true))
            return false;
    }

    if(pJson.isMember("bonus_earned"))
    {
        if(!validJsonOfField(5, "bonus_earned", pJson["bonus_earned"], err, true))
            return false;
    }

    return true;
}
